<template>
  <div class="page-container">
    <el-card shadow="never">
      <div slot="header" style="font-size:18px;font-weight:600;">用户管理</div>
      <el-table :data="users" stripe v-loading="loading">
        <el-table-column prop="id" label="ID" width="70" />
        <el-table-column prop="username" label="用户名" width="120" />
        <el-table-column prop="real_name" label="真实姓名" width="120" />
        <el-table-column prop="role" label="角色" width="120">
          <template slot-scope="{ row }">
            <el-tag :type="row.role === 'admin' ? 'danger' : row.role === 'maintenance' ? 'warning' : ''">
              {{ roleMap[row.role] }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column prop="phone" label="手机号" width="140" />
        <el-table-column prop="created_at" label="注册时间">
          <template slot-scope="{ row }">{{ formatDate(row.created_at) }}</template>
        </el-table-column>
      </el-table>
    </el-card>
  </div>
</template>

<script>
import { authApi } from '../../api'

export default {
  name: 'UserManageView',
  data() {
    return {
      users: [],
      loading: false,
      roleMap: { admin: '管理员', teacher: '教师', student: '学生', maintenance: '维修人员' }
    }
  },
  mounted() {
    this.fetchUsers()
  },
  methods: {
    formatDate(d) {
      return d ? new Date(d).toLocaleString('zh-CN') : ''
    },
    async fetchUsers() {
      this.loading = true
      try {
        const res = await authApi.getUsers()
        if (res.code === 200) {
          this.users = res.data
        }
      } finally {
        this.loading = false
      }
    }
  }
}
</script>
